{
  "schema_version": 1,
  "observations": [
    {
      "key": "obs_idempotent_def",
      "facet": "property",
      "statement": "A request method is considered idempotent if the intended effect on the server of multiple identical requests with that method is the same as the effect for a single such request.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_idempotent_methods",
      "facet": "property",
      "statement": "PUT, DELETE, and safe request methods are idempotent.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_idempotent_scope",
      "facet": "property",
      "statement": "The idempotent property only applies to what has been requested by the user; a server is free to log each request separately or retain a revision control history.",
      "start_line": 5,
      "end_line": 5
    },
    {
      "key": "obs_retry_mechanism",
      "facet": "mechanism",
      "statement": "Idempotent methods are distinguished because the request can be repeated automatically if a communication failure occurs before the client is able to read the server's response.",
      "start_line": 5,
      "end_line": 5
    },
    {
      "key": "obs_non_idempotent_retry_constraint",
      "facet": "precondition",
      "statement": "A client SHOULD NOT automatically retry a request with a non-idempotent method unless it has some means to know that the request semantics are actually idempotent, or some means to detect that the original request was never applied.",
      "start_line": 7,
      "end_line": 7
    }
  ],
  "claims": [],
  "questions": []
}
